import React, { useEffect, useState } from 'react';
import api from '../api';

// Ce composant affiche le détail d'un document, avec le bouton "Signer"
// visible seulement pour un responsable, et seulement si le document
// n'est pas déjà signé.
function DocumentDetail({ documentId, user, onRetour }) {
    const [document, setDocument] = useState(null);
    const [message, setMessage] = useState('');
    const [afficherFormSignature, setAfficherFormSignature] = useState(false);
    const [clePriveeSaisie, setClePriveeSaisie] = useState('');

    const chargerDocument = async () => {
        try {
            const reponse = await api.get(`/documents/${documentId}`);
            setDocument(reponse.data);
        } catch (err) {
            console.error(err);
        }
    };

    // On charge le document quand le composant s'affiche
    useEffect(() => {
        chargerDocument();
    }, [documentId]);

    // Appelé quand le responsable clique sur "Signer ce document"
    // On affiche le formulaire qui demande de coller la clé privée.
    const handleAfficherFormSignature = () => {
        setAfficherFormSignature(true);
        setMessage('');
    };

    // Appelé quand le responsable confirme la signature avec sa clé privée
    const handleConfirmerSignature = async (e) => {
        e.preventDefault();

        if (!clePriveeSaisie.trim()) {
            setMessage("Veuillez coller votre clé privée pour signer.");
            return;
        }

        try {
            await api.post('/signatures', {
                document_id: document.id,
                user_id: user.id,
                nom_signataire: `${user.prenom} ${user.nom}`,
                role: user.role,
                cle_privee: clePriveeSaisie
            });

            setMessage('Document signé avec succès !');
            setAfficherFormSignature(false);
            setClePriveeSaisie('');
            chargerDocument(); // on recharge le document pour voir le nouveau statut

        } catch (err) {
            console.error(err);
            setMessage('Erreur lors de la signature. Vérifiez votre clé privée.');
        }
    };

    if (!document) {
        return <div className="page-container">Chargement...</div>;
    }

    return (
        <div className="page-container" style={{ maxWidth: '640px' }}>
            <button className="btn btn-secondary btn-sm mb-3" onClick={onRetour}>
                ← Retour à la liste
            </button>

            <div className="card card-accent p-4">
                <h3>{document.titre}</h3>
                <p className="text-muted">
                    Créé par {document.auteur_prenom} {document.auteur_nom} le{' '}
                    {new Date(document.date_creation).toLocaleString()}
                </p>

                <p>{document.description}</p>

                <p>
                    Statut :{' '}
                    {document.statut === 'signe' ? (
                        <span className="badge bg-success">Signé</span>
                    ) : (
                        <span className="badge bg-warning text-dark">En attente</span>
                    )}
                </p>

                {/* Lien pour ouvrir le fichier PDF dans un nouvel onglet */}
                <a
                    className="btn btn-outline-primary mb-3"
                    href={`http://localhost:5000/uploads/${document.fichier_pdf}`}
                    target="_blank"
                    rel="noreferrer"
                >
                    📄 Voir le fichier PDF
                </a>

                {message && <div className="alert alert-info">{message}</div>}

                {/* Le bouton Signer n'apparaît que pour un responsable,
                    et seulement si le document n'est pas encore signé */}
                {user.role === 'responsable' && document.statut === 'en_attente' && !afficherFormSignature && (
                    <button className="btn btn-success" onClick={handleAfficherFormSignature}>
                        ✔️ Signer ce document
                    </button>
                )}

                {/* Formulaire demandant la clé privée pour confirmer la signature */}
                {afficherFormSignature && (
                    <form onSubmit={handleConfirmerSignature} className="mt-2">
                        <label className="form-label">
                            Collez votre clé privée pour signer ce document
                        </label>
                        <textarea
                            className="form-control mb-2"
                            rows={6}
                            placeholder="-----BEGIN RSA PRIVATE KEY-----"
                            value={clePriveeSaisie}
                            onChange={(e) => setClePriveeSaisie(e.target.value)}
                            required
                        />
                        <div className="d-flex gap-2">
                            <button type="submit" className="btn btn-success">
                                Confirmer la signature
                            </button>
                            <button
                                type="button"
                                className="btn btn-secondary"
                                onClick={() => { setAfficherFormSignature(false); setClePriveeSaisie(''); }}
                            >
                                Annuler
                            </button>
                        </div>
                    </form>
                )}
            </div>
        </div>
    );
}

export default DocumentDetail;
